{
  "correction_rules": [
    "Bias correction: Model consistently overestimates prices in early forecast periods; reduce initial forecast by 1-2% for 1-3 day horizons.",
    "Lag correction: Model often lags true price movements by 1-2 days; adjust forecast to align with recent 3-5 day true price trend.",
    "Overshoot after spikes: After sharp price spikes, model tends to overcorrect downward; apply a 0.5-1.0% upward bias to prevent premature reversal.",
    "Mean reversion: Model underestimates mean-reversion strength; add 0.5-1.5% upward adjustment if price deviates >3% from 30-day moving average.",
    "Sentiment sensitivity: When sentiment = 0.00 (neutral), model should not amplify volatility; apply smoothing filter to reduce forecast noise.",
    "Horizon-specific: 30-day forecasts show persistent underestimation of late-period price surges; increase forecast by 1-2% for days 25-30 of horizon."
  ]
}
